mapper.select:
SELECT instance_id AS "instanceId", date_trunc(#{truncUnit}, tm) AS "bucket", AVG(CASE WHEN #{metricKey} = 'cpuUsage' THEN cpu_per WHEN #{metricKey} = 'serverMemUsage' THEN mem_server_per WHEN #{metricKey} = 'redisMemUsed' THEN mem_us WHEN #{metricKey} = 'qps' THEN ops WHEN #{metricKey} = 'avgLatency' THEN cmd_latency WHEN #{metricKey} = 'netInputBandwidth' THEN io_iik WHEN #{metricKey} = 'netOutputBandwidth' THEN io_iok END) AS "value" FROM rms_metric_log WHERE instance_id IN
#{id}
AND tm BETWEEN #{startTime} AND #{endTime} GROUP BY instance_id, date_trunc(#{truncUnit}, tm) ORDER BY bucket
